from typing import List, Union
from functools import reduce

def mean_absolute_deviation(numbers: List[float]) -> Union[float, str]:
    if any(isinstance(x, str) for x in numbers):
        return 'Error'
    n = len(numbers)
    if n == 0:
        return '0.0'
    mean = sum(numbers) / n
    abs_diffs = list(map(lambda x: abs(x - mean), numbers))
    mad = sum(abs_diffs) / n
    return str(mad)

def monotonic(l):
    # Check duplicates
    if len(set(l)) != len(l):
        return False

    # For list input
    if isinstance(l, list):
        # Check monotonic increasing: all previous < next
        def strictly_increasing(lst):
            if len(lst) < 2:
                return True
            return lst[0] < lst[1] and strictly_increasing(lst[1:])

        # Check monotonic decreasing
        def strictly_decreasing(lst):
            if len(lst) < 2:
                return True
            return lst[0] > lst[1] and strictly_decreasing(lst[1:])

        if strictly_increasing(l) or strictly_decreasing(l):
            return True, sum(l)
        else:
            return False

    # For string input
    elif isinstance(l, str):
        # Check strictly increasing chars
        def strictly_increasing_str(s):
            if len(s) < 2:
                return True
            return s[0] < s[1] and strictly_increasing_str(s[1:])

        # Check strictly decreasing chars
        def strictly_decreasing_str(s):
            if len(s) < 2:
                return True
            return s[0] > s[1] and strictly_decreasing_str(s[1:])

        if strictly_increasing_str(l) or strictly_decreasing_str(l):
            return True, l
        else:
            return False

    else:
        # If input is neither list nor str, return False
        return False

def digits(n):
    s = str(n)
    odds = [int(d) for d in s if int(d) % 2 == 1]
    evens = [int(d) for d in s if int(d) % 2 == 0]

    def prod(lst):
        if not lst:
            return None
        p = 1
        for x in lst:
            p *= x
        return p

    odd_prod = prod(odds)
    even_prod = prod(evens)

    if odd_prod is not None:
        return str(odd_prod) if isinstance(n, str) else odd_prod
    if even_prod is not None:
        return even_prod if isinstance(n, int) else str(even_prod)
    # in case there are no digits (should not happen for positive int or non-empty string)
    return 0

def order_by_points(nums):
    if not nums:
        return []
    def digit_sum(x):
        return sum(map(int, str(abs(int(x)))))
    indexed = list(enumerate(nums))
    sorted_indexed = sorted(indexed, key=lambda iv: digit_sum(iv[1]))
    return ', '.join(str(iv[1]) for iv in sorted_indexed)
